const rawItem = $input.first().json;
// Webhook puts multipart text fields at top level; fallback covers edge cases
const item = rawItem['Universidad'] ? rawItem : (rawItem.body || rawItem);

function defaultPeriodo() {
  const now = new Date();
  return String(now.getMonth() + 1).padStart(2, '0') + '-' + now.getFullYear();
}

function parseNoticias(text) {
  if (!text || !text.trim()) return [];
  return text.trim().split('\n')
    .filter(l => l.trim())
    .map((line, i) => {
      const parts = line.split('|').map(p => p.trim());
      const ts = (parts[2] || '').trim();
      return { idx: i + 1, tematica: parts[0] || '', programa: parts[1] || '', tema_sugerido: ts, necesita_tema: !ts, keywords: [], especificaciones_excluir: [], especificaciones_extra: [], enlaces: [] };
    })
    .filter(n => n.tematica);
}

function parseLinks(text, noticias) {
  if (!text || !text.trim()) return;
  text.trim().split('\n').filter(l => l.trim()).forEach(line => {
    const parts = line.split('|').map(p => p.trim());
    const idx = parseInt(parts[0], 10);
    const noticia = noticias.find(n => n.idx === idx);
    if (noticia && parts[1]) noticia.enlaces.push({ nombre: parts[1], anchor: parts[2] || '' });
  });
}

function parseNumber(raw) {
  if (!raw && raw !== 0) return 0;
  const s = String(raw).replace(/[^0-9.,]/g, '');
  if (!s) return 0;
  let n;
  if (s.includes('.') && s.includes(',')) n = parseFloat(s.replace(/,/g, ''));
  else if (s.includes(',') && /,\d{3}$/.test(s)) n = parseFloat(s.replace(/,/g, ''));
  else n = parseFloat(s.replace(',', '.'));
  return isNaN(n) ? 0 : n;
}

function parseSemrushCSV(content) {
  if (content.charCodeAt(0) === 0xFEFF) content = content.slice(1);
  const firstLine = content.split('\n')[0] || '';
  const sc = (firstLine.match(/;/g) || []).length;
  const co = (firstLine.match(/,/g) || []).length;
  const ta = (firstLine.match(/\t/g) || []).length;
  const delim = ta > sc && ta > co ? '\t' : sc > co ? ';' : ',';
  const lines = content.split('\n').map(l => l.trim()).filter(Boolean);
  if (lines.length < 2) return [];
  const headers = lines[0].split(delim).map(h => h.replace(/"/g, '').trim());
  const lh = headers.map(h => h.toLowerCase());
  const findCol = (aliases) => {
    for (const a of aliases) { const i = lh.indexOf(a.toLowerCase()); if (i >= 0) return i; }
    for (const a of aliases) { const i = lh.findIndex(h => h.includes(a.toLowerCase())); if (i >= 0) return i; }
    return -1;
  };
  const kwIdx = findCol(['keyword', 'phrase', 'palabra clave', 'query', 'ph']);
  const volIdx = findCol(['volume', 'search volume', 'avg. monthly searches', 'volumen', 'nq', 'vol.']);
  const kdIdx = findCol(['keyword difficulty', 'kd', 'difficulty', 'dificultad']);
  if (kwIdx === -1) return [];
  const seen = new Set();
  const result = [];
  for (let i = 1; i < lines.length; i++) {
    const cols = lines[i].split(delim).map(c => c.replace(/"/g, '').trim());
    const kw = cols[kwIdx];
    if (!kw) continue;
    const key = kw.toLowerCase().trim();
    if (seen.has(key)) continue;
    seen.add(key);
    result.push({ kw, vol: volIdx >= 0 ? Math.round(parseNumber(cols[volIdx])) : 0, kd: kdIdx >= 0 ? Math.round(parseNumber(cols[kdIdx])) : 0 });
  }
  return result.sort((a, b) => b.vol - a.vol).slice(0, 80);
}

const universidad = (item['Universidad'] || '').trim();
const periodo = (item['Periodo'] || '').trim() || defaultPeriodo();
const noticias = parseNoticias(item['Noticias'] || '');
if (!noticias.length) throw new Error('Completar el campo Noticias: "tematica | programa" una por linea.');
parseLinks(item['Links'] || '', noticias);

let allKeywords = [];
const binary = $input.first().binary || {};
const csvKey = Object.keys(binary).find(k => {
  const fname = (binary[k].fileName || k).toLowerCase();
  return fname.endsWith('.csv') || fname.endsWith('.txt');
});
if (csvKey) {
  const buf = await this.helpers.getBinaryDataBuffer($input.first(), csvKey);
  let content = buf.toString('utf-8');
  if (content.includes('�')) content = buf.toString('latin1');
  allKeywords = parseSemrushCSV(content);
}

return [{ json: { universidad, periodo, noticias, allKeywords } }];

